"""Create a concise Turkish interpretation and a portable desktop report from a completed dataset."""
import csv,json,statistics,sys,html
from pathlib import Path
p=Path(sys.argv[1]); out=Path(sys.argv[2]);out.mkdir(parents=True,exist_ok=True)
status=json.loads((p/'status.json').read_text());manifest=json.loads((p/'manifest.json').read_text())
if status['completed']!=status['planned'] or status['failed'] or status['missing']:raise SystemExit('Dataset is not complete')
def load(name):
 with (p/name).open() as f:return list(csv.DictReader(f))
metrics=load('metrics.csv');effects=load('effects.csv');checks=load('checks.csv');pairs=load('paired_comparisons.csv')
def percentile(values,q):
 a=sorted(values);i=(len(a)-1)*q;lo=int(i);return a[lo]+(a[min(lo+1,len(a)-1)]-a[lo])*(i-lo)
def stats(rows):
 a=[float(r['tunnel_rmse_m']) for r in rows];return [statistics.median(a),percentile(a,.9),max(a)]
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+ '|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(map(str,r))+' |' for r in rows)+'\n'
labels={'a':'Sabit hız','c':'İvme takibi · Kalman','b':'Gelişmiş füzyon · IMM-EKF'}
ref=[r for r in metrics if r['stage']=='reference' and r['split']=='development'];validation=[r for r in metrics if r['stage']=='reference' and r['split']=='validation']
sections=['# Tünel simülatörü — veri seti ve kontrol raporu\n',f"**{status['completed']:,} koşu tamamlandı.** Hesaplama hatası: {status['failed']}; eksik koşu: {status['missing']}; bağımsızlık kontrolü: {status['invariant_checks']:,}; ihlal: {status['invariant_failures']}.\n"]
sections+=['## Deney tasarımı\n','240 geliştirme referansı; 1.800 sayısal alt/üst değer taraması; 300 açık/kapalı kontrolü; 540 telefon, harita, NIS, hız ve tünel uzunluğu taraması; 120 ayrı seed doğrulama referansı; 180 birleşik zor koşul. Geliştirme seedleri 1001–1020, doğrulama seedleri 9001–9010. Parametreler doğrulama sonuçlarına göre ayarlanmadı.\n','Üç yol ve dört sürüş profilinin referansları var. Parametreler tek tek değiştirilir; varsayılan değer aynı seed/yol/profil referansından alınır. Wavespeed parametreleri Wavespeed profilinde, duruş anahtarları duruş profilinde, diğer taramalar yavaşlama profilinde sınanır. Tüm etkileşimlerin Kartezyen çarpımı taranmaz.\n']
for title,rows in [('Geliştirme referansları — koşu başına tünel RMSE',ref),('Ayrı seed doğrulaması — koşu başına tünel RMSE',validation)]:
 sections += ['## '+title+'\n',table(['Model','Medyan (m)','P90 (m)','En kötü (m)'],[[labels[k],*[f'{v:.2f}' for v in stats([r for r in rows if r['model']==k])]] for k in ['a','c','b']])]
sections+=['## Sürüşe göre geliştirme referansları\n',table(['Sürüş','Sabit hız medyan RMSE','Kalman medyan RMSE','IMM-EKF medyan RMSE'],[[profile,*[f"{statistics.median(float(r['tunnel_rmse_m']) for r in ref if r['profile']==profile and r['model']==k):.2f} m" for k in ['a','c','b']]] for profile in ['steady','slowdown','stop','wavespeed']]),'Bu tablolar tek koşuların metriklerini özetler; zaman örnekleri havuzlanmaz. Kalman her koşulda sabit hızdan iyi olmak zorunda değildir.\n']
audit=[]
for factor,level in sorted({(r['factor'],r['level']) for r in effects if r['split']=='development'}):
 rows=[r for r in effects if r['split']=='development' and r['factor']==factor and r['level']==level]; audit.append({'factor':factor,'level':level,**{k+'_changed_of_n':next((r['changed_runs']+'/'+r['n'] for r in rows if r['model']==k),'') for k in ['a','c','b']},**{k+'_mean_delta_rmse_m':next((r['mean_delta_rmse_m'] for r in rows if r['model']==k),'') for k in ['a','c','b']}})
with (out/'control-audit.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(audit[0]));w.writeheader();w.writerows(audit)
stop=[r for r in ref if r['profile']=='stop'];cstop=[r for r in stop if r['model']=='c'];bstop=[r for r in stop if r['model']=='b'];true_stops=sum(int(r['stopped_samples']) for r in cstop);c_detected=sum(int(r['detected_stopped_samples']) for r in cstop);b_detected=sum(int(r['detected_stopped_samples']) for r in bstop)
sections+=['## Öne çıkan kontrol bulgusu\n',f'Kalman ZUPT anahtarını kapatmak 60 geliştirme duruş koşusunun hiçbirinde çıktıyı değiştirmedi. Bu koşullarda {true_stops:,} gerçek duruş örneğinin {c_detected:,} tanesi Kalman tarafından duruş olarak işaretlendi; IMM-EKF aynı örneklerin {b_detected:,} tanesini işaretledi. Bu, Kalman duruş koşullarının bu senaryolarda tetiklenmediğini gösterir. Filtrenin sentetik düşük hız/düşük belirsizlik birim testleri geçiyor; buna rağmen mevcut fiziksel sürüşlerde ZUPT faydası gözlenmedi. Bu bulgu ayrıca incelenmeli; algoritmayı bu veri üretimi sırasında değiştirmedik.\n']
sections+=['## Kontrollerin gözlenen etkisi\n','Aşağıdaki sayılar, aynı seedli referanstan farklı tahmin çıktısı üreten koşu sayısıdır. Aynı çıktı, kontrolün bozuk olduğunu tek başına göstermez: olay gerçekleşmemiş veya ölçüm kapıdan geçmemiş olabilir. Kontrol testi, sonuç etkisi ve başarı ayrı değerlendirilmelidir.\n',table(['Kontrol','Seviye','Sabit hız','Kalman','IMM-EKF'],[[r['factor'],r['level'],r['a_changed_of_n'],r['c_changed_of_n'],r['b_changed_of_n']] for r in audit])]
sections+=['## En belirgin eşleştirilmiş etkiler\n','ΔRMSE = varyant − referans. Pozitif değer hata artışıdır. Ortalamalar aynı seed/yol/profil eşleşmelerinden hesaplanır; %95 aralıklar seed kümeleriyle 2.000 bootstrap tekrarından gelir. Çoklu karşılaştırma düzeltmesi yapılmadı; bulgular keşif amaçlıdır.\n']
for k in ['c','b']:
 rows=sorted([r for r in effects if r['split']=='development' and r['model']==k],key=lambda r:float(r['mean_delta_rmse_m']),reverse=True)
 sections+=['### '+labels[k]+'\n',table(['Kontrol','Seviye','Ortalama ΔRMSE (m)','%95 aralık (m)'],[[r['factor'],r['level'],f"{float(r['mean_delta_rmse_m']):+.2f}",f"[{float(r['cluster_bootstrap_95_low_m']):+.2f}, {float(r['cluster_bootstrap_95_high_m']):+.2f}]"] for r in rows[:5]])]
sections+=['## Dikkat edilmesi gerekenler\n','- Kalibrasyon uzunluğunu değiştirmek sürüş/sensör geçmişini de değiştirir. Aynı seed, farklı uzunluklarda aynı fiziksel kayıt demek değildir. 180 saniye yeterlilik garantisi değildir; hazırlık eşikleri belirleyicidir.\n- R/Q, IMU gürültüsü ve bias etkileri hazırlık kapıları nedeniyle doğrusal veya tek yönde olmak zorunda değildir.\n- Kartlardaki tüm süreç tepe hatası ile tünel içi tepe hata ayrı sütunlardır.\n- Toparlanma ölçüsü fiziksel çıkıştan itibaren, kayıt sonuna kadar hatanın 10 m altında kaldığı ilk örnektir. Boş değer yaklaşık 18 saniyelik çıkış sonrası pencerede sağlanmadığını belirtir; sıfır değildir.\n- Birleşik stres koşulları bireysel nedenleri ayırmaz. Sentetik sonuçlar gerçek telefon doğruluğunu kanıtlamaz.\n- GUI dil/oynatma ayarları sayısal motora girmez; bu tarama sayısal değişkenleri kapsar. Canlı hız komutlarının geçmişi koruma davranışı mevcut otomatik testlerde sınanır; bu veri setinde ayrı bir canlı komut taraması yoktur.\n']
worst=sorted(metrics,key=lambda r:float(r['tunnel_rmse_m']),reverse=True)[:10]
sections+=['## Yeniden incelenmesi gereken en yüksek hatalı koşular\n',table(['Run ID','Model','Aşama','Yol / sürüş','RMSE (m)'],[[r['run_id'],r['model'],r['stage'],r['road']+' / '+r['profile'],f"{float(r['tunnel_rmse_m']):.2f}"] for r in worst]),'## Dosyalar ve yeniden üretim\n',f"Kod revizyonu: `{manifest['git_commit']}`. `manifest.json` kaynak checksumlarını ve runtime sürümünü içerir; `source/` tam üretim kaynaklarını saklar. `plan.json` bütün koşulların ayarlarını içerir. `runs/<id>.json` tam hassasiyetli metrikler ve ayarlardır.\n",'`metrics.csv`: model başına sonuçlar; `paired_comparisons.csv`: referans farkları; `aggregates.csv`: yol/sürüş grupları; `effects.csv`: etki ve aralıklar; `checks.csv`: bağımsızlık denetimleri; `control-audit.csv`: kontrol özeti.\n','`timeseries/*.csv.gz` 10 Hz motor çıktılarını dokuz ondalığa yuvarlanmış olarak içerir. Tam ham 100 Hz üç eksenli IMU kaydı değildir. Kalibrasyon bölümünde tahmin alanları boş bırakılır. Zaman sıfırı kalibrasyon sonudur; `elapsed_s` kalibrasyonu da içerir.\n','```sh\nnode scripts/dataset.js --out ./data/tunnel-dataset-v1 --workers 4\n```\nAynı komut doğrulanmış tamamlanan koşuları atlayarak devam eder. Başka plan/kod için başka klasör gerekir.\n']
text='\n'.join(sections);(out/'Tunnel-dataset-summary.md').write_text(text)
# Portable presentation with sortable numerical results, no network or external libraries.
payload=[{k:r[k] for k in ['stage','split','road','profile','seed','factor','level','model','tunnel_rmse_m','tunnel_peak_m','coverage_2sigma','run_id']} for r in metrics]
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Tunnel dataset results</title><style>body{font:14px system-ui;margin:32px;background:#f6f8f6;color:#22372f}h1{font-size:28px}select,input,button{padding:9px;margin:0 12px 12px 0}table{border-collapse:collapse;width:100%;background:white}th,td{padding:9px;text-align:left;border-bottom:1px solid #e2e9e4}th{cursor:pointer;position:sticky;top:0;background:#e5f0e9}p{line-height:1.6}.muted{color:#6a7d70}</style><h1>Tunnel simulator · dataset results</h1><p>3,180 synthetic runs. A: constant speed · C: acceleration tracking · B: IMM-EKF.<br>RMSE and peak below cover the tunnel only. Click column headers to sort. Full metrics and paired comparisons are available in the dataset CSV files.</p><select id="split"><option value="">All splits</option><option>development</option><option>validation</option></select><select id="stage"><option value="">All stages</option><option>reference</option><option>numeric</option><option>switch</option><option>selection</option><option>stress</option></select><select id="model"><option value="">All models</option><option>a</option><option>c</option><option>b</option></select><input id="search" placeholder="Search factor, road, profile or run ID"><p id="count"></p><table><thead id="head"></thead><tbody id="body"></tbody></table><script>const rows=PAYLOAD,cols=['stage','split','road','profile','seed','factor','level','model','tunnel_rmse_m','tunnel_peak_m','coverage_2sigma','run_id'];let sort='tunnel_rmse_m',direction=-1;const $=x=>document.getElementById(x);$('head').innerHTML='<tr>'+cols.map(c=>'<th data-key="'+c+'">'+c+'</th>').join('')+'</tr>';function render(){let a=rows.filter(r=>['split','stage','model'].every(k=>!$(k).value||r[k]===$(k).value)&&Object.values(r).join(' ').toLowerCase().includes($('search').value.toLowerCase()));a.sort((a,b)=>direction*(isNaN(Number(a[sort]))?a[sort].localeCompare(b[sort]):Number(a[sort])-Number(b[sort])));$('count').textContent=a.length+' model results · first 300 shown';$('body').innerHTML=a.slice(0,300).map(r=>'<tr>'+cols.map(k=>'<td>'+(['tunnel_rmse_m','tunnel_peak_m'].includes(k)?Number(r[k]).toFixed(2):k==='coverage_2sigma'?(100*Number(r[k])).toFixed(1)+'%':r[k])+'</td>').join('')+'</tr>').join('');}for(const k of ['split','stage','model','search'])$(k).oninput=render;$('head').onclick=e=>{if(e.target.dataset.key){sort=e.target.dataset.key;direction*=-1;render();}};render();</script></html>'''
(out/'Tunnel-dataset-results.html').write_text(page.replace('PAYLOAD',json.dumps(payload,separators=(',',':'))))
print(json.dumps({'report':str(out/'Tunnel-dataset-summary.md'),'model_rows':len(metrics),'controls':len(audit),'invariant_failures':status['invariant_failures']}))
